function floorTracker(operations) {
  const stack = [], results = [];
  for (const op of operations) {
    if (op[0] === 'push') stack.push(op[1]);
    else if (op[0] === 'pop') results.push(stack.pop());
    else if (op[0] === 'top') results.push(stack[stack.length - 1]);
    else results.push(Math.min(...stack));
  }
  return results;
}

function floorTracker(operations) {
  const values = [], minimums = [], results = [];
  for (const op of operations) {
    if (op[0] === 'push') {
      const x = op[1];
      values.push(x);
      minimums.push(minimums.length ? Math.min(minimums[minimums.length - 1], x) : x);
    } else if (op[0] === 'pop') {
      minimums.pop();
      results.push(values.pop());
    } else if (op[0] === 'top') results.push(values[values.length - 1]);
    else results.push(minimums[minimums.length - 1]);
  }
  return results;
}
